const input = $json.body || $json;
const jaar = parseInt(input.jaar) || 2025;
const periode = input.periode || 'Q1 (Jan-Mrt)';
const maanden = {
  'Januari':1,'Februari':2,'Maart':3,'April':4,'Mei':5,'Juni':6,
  'Juli':7,'Augustus':8,'September':9,'Oktober':10,'November':11,'December':12
};
let kwartaal_nr = 0, maand_nr = 0, periode_label = '';
if      (periode.startsWith('Q1')) { kwartaal_nr=1; periode_label=`Q1 Jan-Mrt ${jaar}`; }
else if (periode.startsWith('Q2')) { kwartaal_nr=2; periode_label=`Q2 Apr-Jun ${jaar}`; }
else if (periode.startsWith('Q3')) { kwartaal_nr=3; periode_label=`Q3 Jul-Sep ${jaar}`; }
else if (periode.startsWith('Q4')) { kwartaal_nr=4; periode_label=`Q4 Okt-Dec ${jaar}`; }
else if (periode === 'Heel jaar')   { periode_label=`Heel jaar ${jaar}`; }
else if (maanden[periode])         { maand_nr=maanden[periode]; periode_label=`${periode} ${jaar}`; }
else                               { periode_label=`${periode} ${jaar}`; }
return [{ json: { jaar, kwartaal_nr, maand_nr, periode_label } }];

function fmt(val) {
  const v = parseFloat(val||0);
  return '€ ' + v.toLocaleString('nl-NL',{minimumFractionDigits:2,maximumFractionDigits:2});
}
const d = $json;
const o21=parseFloat(d.omzet_21||0), o9=parseFloat(d.omzet_9||0), o0=parseFloat(d.omzet_0||0);
const oTot=o21+o9+o0;
const bo21=parseFloat(d.btw_omzet_21||0), bo9=parseFloat(d.btw_omzet_9||0);
const boTot=bo21+bo9;
const k21=parseFloat(d.kosten_21||0), k9=parseFloat(d.kosten_9||0), k0=parseFloat(d.kosten_0||0);
const kTot=k21+k9+k0;
const bk21=parseFloat(d.btw_kosten_21||0), bk9=parseFloat(d.btw_kosten_9||0);
const bkTot=bk21+bk9;
const btwSaldo=boTot-bkTot;
const netto=oTot-kTot;
return [{json:{
  periode_label: d.periode_label,
  factuur_count: d.factuur_count+' facturen',
  inkoop_count:  d.inkoop_count+' boekingen',
  omzet_21: fmt(o21), omzet_9: fmt(o9), omzet_0: fmt(o0),
  omzet_totaal: fmt(oTot),
  btw_omzet_21: fmt(bo21), btw_omzet_9: fmt(bo9), btw_omzet_totaal: fmt(boTot),
  kosten_21: fmt(k21), kosten_9: fmt(k9), kosten_0: fmt(k0),
  kosten_totaal: fmt(kTot),
  btw_kosten_21: fmt(bk21), btw_kosten_9: fmt(bk9), btw_kosten_totaal: fmt(bkTot),
  btw_saldo: btwSaldo>=0 ? fmt(btwSaldo)+' te betalen' : fmt(Math.abs(btwSaldo))+' terug te ontvangen',
  netto_resultaat: netto>=0 ? fmt(netto)+' winst' : fmt(Math.abs(netto))+' verlies',
  _o21:o21,_o9:o9,_o0:o0,_oTot:oTot,
  _bo21:bo21,_bo9:bo9,_boTot:boTot,
  _k21:k21,_k9:k9,_k0:k0,_kTot:kTot,
  _bk21:bk21,_bk9:bk9,_bkTot:bkTot,
  _btwSaldo:btwSaldo,_netto:netto
}}];

